from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    results = []
    for group in paren_string.split():
        max_depth = 0
        current_depth = 0
        for char in group:
            if char == '(':  
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1
        results.append(max_depth)
    return results

from typing import List, Tuple

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    total_sum = sum(numbers)
    total_product = 1
    for number in numbers:
        total_product *= number
    return (total_sum, total_product)

from typing import List

def remove_duplicates(numbers: List[int]) -> List[int]:
    counts = {}
    for number in numbers:
        counts[number] = counts.get(number, 0) + 1
    return [number for number in numbers if counts[number] == 1]

def fizz_buzz(n: int):
    count = 0
    for i in range(n):
        if i % 11 == 0 or i % 13 == 0:
            count += str(i).count('7')
    # Check for numbers divisible by 11 or 13
    count += str(7).count('7')
    count += str(77).count('7')
    return count

def median(l: list):
    """Return median of elements in the list l."""
    sorted_l = sorted(l)
    n = len(sorted_l)
    mid = n // 2
    if n % 2 == 1:
        return sorted_l[mid]
    else:
        return (sorted_l[mid - 1] + sorted_l[mid]) / 2

def monotonic(l: list):
    if not l:
        return True
    increasing = decreasing = True
    for i in range(1, len(l)):
        if l[i] > l[i - 1]:
            decreasing = False
        elif l[i] < l[i - 1]:
            increasing = False
    return increasing or decreasing

def largest_prime_factor(n: int):
    """Return the largest prime factor of n. Assume n > 1 and is not a prime."""
    largest_factor = 1
    factor = 2
    while factor * factor <= n:
        if n % factor == 0:
            largest_factor = factor
            n //= factor
        else:
            factor += 1
    if n > 1:
        largest_factor = n
    return largest_factor

def correct_bracketing(brackets: str):
    count = 0
    for char in brackets:
        if char == '(':  
            count += 1
        elif char == ')':
            count -= 1
        if count < 0:
            return False
    return count == 0

def vowels_count(s):
    vowels = 'aeiou'
    count = sum(1 for char in s.lower() if char in vowels)
    if s.endswith('y') or s.endswith('Y'):
        count += 1
    return count

def total_match(lst1, lst2):
    total_chars_lst1 = sum(len(s) for s in lst1)
    total_chars_lst2 = sum(len(s) for s in lst2)
    if total_chars_lst1 >= total_chars_lst2:
        return lst2
    return lst1

