def anti_shuffle(s):
    result = []
    current_word = []
    for char in s:
        if char == ' ':
            if current_word:
                result.append(''.join(sorted(current_word)))
                current_word = []
            result.append(char)
        else:
            current_word.append(char)
    if current_word:
        result.append(''.join(sorted(current_word)))
    return ''.join(result)

def next_smallest(lst):
    unique_elements = list(set(lst))
    if len(unique_elements) < 2:
        return None
    unique_elements.sort()
    return unique_elements[1]

def max_fill(grid, capacity):
    total_water = sum(sum(row) for row in grid)
    return (total_water + capacity - 1) // capacity

def minPath(grid, k):
    from collections import deque
    n = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    min_path = None

    def bfs(start_row, start_col):
        queue = deque([(start_row, start_col, [grid[start_row][start_col]])])
        while queue:
            row, col, path = queue.popleft()
            if len(path) == k:
                nonlocal min_path
                if min_path is None or path < min_path:
                    min_path = path
                continue
            for dr, dc in directions:
                new_row, new_col = row + dr, col + dc
                if 0 <= new_row < n and 0 <= new_col < n:
                    queue.append((new_row, new_col, path + [grid[new_row][new_col]]))

    for i in range(n):
        for j in range(n):
            bfs(i, j)

    return min_path

def sum_squares(lst):
    total = 0
    for i, value in enumerate(lst):
        if i % 3 == 0:
            total += value ** 2
        if i % 4 == 0 and i % 3 != 0:
            total += value ** 3
        if i % 3 != 0 and i % 4 != 0:
            total += value
    return total

def order_by_points(nums):
    def sum_of_digits(n):
        return sum(int(digit) for digit in str(abs(n)))
    return sorted(nums, key=lambda x: (sum_of_digits(x), nums.index(x)))

def is_prime(num):
    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise."""
    return x if is_prime(n) else y

def even_odd_count(num):
    """Given an integer. return a tuple that has the number of even and odd digits respectively.

     Example:
        even_odd_count(-12) ==> (1, 1)
        even_odd_count(123) ==> (1, 2)
    """
    even_count = 0
    odd_count = 0
    for digit in str(abs(num)):
        if int(digit) % 2 == 0:
            even_count += 1
        else:
            odd_count += 1
    return (even_count, odd_count)

import hashlib

def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if text == '':
        return None
    return hashlib.md5(text.encode()).hexdigest()
